CREATE TABLE IF NOT EXISTS revenue_changes (id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,property_ref TEXT NOT NULL,stay_date DATE NOT NULL,room_type TEXT NOT NULL,inventory INTEGER NOT NULL,reservations INTEGER NOT NULL,current_rate NUMERIC(12,2) NOT NULL,recommended_rate NUMERIC(12,2),restrictions JSONB NOT NULL DEFAULT '{}'::jsonb,data_as_of TIMESTAMPTZ NOT NULL,evidence JSONB NOT NULL DEFAULT '[]'::jsonb,status TEXT NOT NULL DEFAULT 'draft',provider_receipt TEXT,rollback_snapshot JSONB,measurement JSONB,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_by BIGINT NOT NULL,approved_by BIGINT,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key),CHECK(status IN ('draft','recommended','review','approved','published','rolled_back','measured')),CHECK(inventory>=0 AND reservations>=0 AND reservations<=inventory));
CREATE TABLE IF NOT EXISTS revenue_integration_runs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL,operation TEXT NOT NULL,status TEXT NOT NULL,data_as_of TIMESTAMPTZ,external_reference TEXT,error_code TEXT,error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status IN ('queued','succeeded','failed','stale','partial')));
CREATE TABLE IF NOT EXISTS revenue_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,actor_user_id BIGINT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,before_state JSONB,after_state JSONB,request_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS revenue_change_scope_idx ON revenue_changes(tenant_id,property_ref,stay_date,status);
